API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Proxy, "Edge Proxy", "Stateless edge proxy deployed on on-prem-k8s and eu-central-1", "Routes external traffic and terminates secure client traffic at the edge with TLS 1.3.")
    Component(Routing_and_Validation_Engine, "Routing and Validation Engine", "OpenAPI, GitOps", "Enforces declarative infrastructure routing and strict contract validation at the edge.")
}

Rel(Edge_Proxy, Routing_and_Validation_Engine, "Validates and routes requests", "HTTPS, MFA")

@enduml

EMR Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(emr_service_container, "EMR Service") {
    Component(emr_api_controller, "EMR API Controller", "Microservice / REST, gRPC", "Handles incoming routing requests from the API Gateway and exposes endpoints for clinical records.")
    Component(cqrs_handler, "CQRS Command/Query Handler", "CQRS Pattern", "Separates read and write operations on patient records for performance optimization.")
    Component(abac_engine, "ABAC Enforcement Engine", "Attribute-Based Access Control", "Enforces strict HIPAA/GDPR compliance and access control policies for patient data.")
    Component(fhir_adapter, "FHIR Interoperability Adapter", "HL7 FHIR", "Serializes and deserializes data for seamless interoperability with external labs and imaging systems.")
}

Rel(emr_api_controller, cqrs_handler, "Delegates read and write operations")
Rel(cqrs_handler, abac_engine, "Validates access permissions for data operations")
Rel(cqrs_handler, fhir_adapter, "Transforms clinical data to standardized formats")

@enduml

Caching Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Caching Layer container

Container_Boundary(caching_layer, "Caching Layer") {
    Component(RedisPrimaryReplicaStore, "Redis Primary-Replica Store", "Redis with Redis Sentinel/Cluster", "In-memory store with LRU eviction and memory-wiping mechanisms providing low latency and high availability.")
    Component(AccessControlLayerACL, "Access Control Layer (ACL)", "Redis ACL", "Restricts key-spaces to ensure strict HIPAA and GDPR compliance regulations.")
    Component(EventInvalidationListener, "Event Invalidation Listener", "AMQP/Kafka Client", "Receives asynchronous event-driven invalidation signals from the message broker.")
}

Rel(EventInvalidationListener, RedisPrimaryReplicaStore, "Triggers cache invalidation upon receiving events", "In-memory Redis Protocol over TLS 1.3")

@enduml

Message Brokers.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Message Brokers container

Container_Boundary(message_brokers, "Message Brokers") {
    Component(Persistent_Message_Queues, "Persistent Message Queues", "Persistent Message Queues with Tiered Storage", "Ensures reliable asynchronous event-driven communication and data integrity across hybrid boundaries.")
    Component(Dead_Letter_Routing, "Dead-Letter Routing", "Message Broker Routing Engine", "Handles undeliverable messages and failed event processing for system resilience.")
}

Rel(Persistent_Message_Queues, Dead_Letter_Routing, "Routes failed messages to")

@enduml
